Add a cancel() method to this class. A cancelled job must never run again.

class Job:
    def __init__(self, fn):
        self.fn = fn
        self.is_running = False
        self.is_done = False
        self.has_error = False

    def run(self):
        if self.is_running or self.is_done:
            return
        self.is_running = True
        try:
            self.fn()
            self.is_done = True
        except Exception:
            self.has_error = True
        self.is_running = False

    def retry(self):
        if self.has_error:
            self.has_error = False
            self.run()

