This crashes now and then under load. I think we need more locking in evict(). Fix it.

Entry *cache_get(Cache *c, int key) {
    pthread_mutex_lock(&c->mu);
    Entry *e = table_lookup(c->table, key);
    pthread_mutex_unlock(&c->mu);
    return e;   /* caller reads e->data */
}

void cache_evict(Cache *c, int key) {
    pthread_mutex_lock(&c->mu);
    Entry *e = table_remove(c->table, key);
    pthread_mutex_unlock(&c->mu);
    free(e);
}

Add pop_back() to this. Also, is_full sometimes seems to be wrong.

class Ring:
    def __init__(self, n):
        self.buf = [None]*n
        self.head = 0
        self.tail = 0
        self.is_full = False

    def push_back(self, x):
        self.buf[self.tail] = x
        self.tail = (self.tail + 1) % len(self.buf)
        if self.is_full:
            self.head = self.tail
        self.is_full = self.tail == self.head

    def pop_front(self):
        if self.head == self.tail and not self.is_full:
            raise IndexError
        x = self.buf[self.head]
        self.head = (self.head + 1) % len(self.buf)
        return x

parse_scores() returns None for an empty file but a list otherwise, so every caller needs an if. Change it to return [] for empty files.

def parse_scores(path):
    text = open(path).read()
    if not text:
        return None
    return [int(l) for l in text.split() if l != 'N/A']

